package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.util.*;
public final class PestSpraySelectionIntegrationTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static class P extends PestSpraySelectionTaskTest.F implements PestSprayTask.Port {
  final PestSprayTask parent=new PestSprayTask(session,coordinator,items,cursors,this);final PestSprayTabReceipts tabs=new PestSprayTabReceipts();final Object tabRow=new Object();PestSprayTabReceipts.Proof tab;PestSprayObservation spray=new PestSprayObservation(PestSprayObservation.State.NONE);int uses,equips,restores,demands,disposals;boolean selectedUpdate,failSelection,deferTab,tickDuringStart,rearmDuringStart;int waitingTab;AutomationSession.Handle actualRoot;
  P(){super(false);selected=0;applyTab();}
  void applyTab(){var scope=new PestSprayTabReceipts.Scope(1,level,player,1,positionEpoch,positionSequence);var entries=List.of("Pests:","Spray: "+(spray.state()==PestSprayObservation.State.NONE?"None":"Test Material (29m)"));tabs.observe(scope,tabRow,entries,1,now);tab=tabs.current(scope,tabRow,entries,now).orElseThrow();}
  @Override public AutomationContext context(){if(parent!=null&&parent.state()==PestSprayTask.State.STARTING_SELECTION){if(tickDuringStart){tickDuringStart=false;parent.tick(now);}if(rearmDuringStart){rearmDuringStart=false;parent.cancel(now);session.invalidate();context=new AutomationContext(1,true,true,Set.of());check(parent.request(PestSprayPlanTest.policy(),now),"explicit new manual generation accepted during stale selection preflight");}}return context;}
  @Override PestSprayTask.Frame motion(long at){return new PestSprayTask.Frame(world,at,level,player,inv,cursor,selected,menu==null,false,x,72,z,0,0,0,yaw,0,tab==null?PestSprayObservation.unknown():spray,positionEpoch,positionSequence,tab);}
  public PestSprayTask.Frame sprayFrame(long at){return motion(at);}public void requestSprayData(AutomationSession.Handle h){actualRoot=h;demands++;}public Optional<Map<String,String>> sprayCatalog(AutomationSession.Handle h){return Optional.of(Map.of("Test Material","TEST_MATERIAL"));}public void disposeSprayData(AutomationSession.Handle h){disposals++;}
  public PestSprayTask.Effect sprayEffect(AutomationSession.Handle h,PestSprayTask.Action a,long at){if(!a.claim(h,motion(at),at))return PestSprayTask.Effect.REJECTED;switch(a.kind()){case EQUIP->{selected=4;equips++;}case RESTORE->{selected=0;restores++;}case USE->{uses++;inv=new HashMap<>(inv);inv.put(9,PestSprayPlanTest.material(9));items.observe(1,0,9,inv.get(9));parent.onSystemMessage(1,"Sprayonator! You sprayed plot 1!",at);spray=new PestSprayObservation(PestSprayObservation.State.ACTIVE);applyTab();}}return PestSprayTask.Effect.SENT;}
  @Override public PestSprayTask.Effect selectionEffect(AutomationSession.Handle h,PestSpraySelectionTask.Action a,long at){check(h.equals(actualRoot)&&session.isCurrent(h)&&session.holdsFarming(),"original parent root/hold must survive child");if(!a.claim(h,selectionFrame(at),at))return PestSprayTask.Effect.REJECTED;switch(a.kind()){case OPEN->{opens++;opening();}case CLICK->clicks++;case CLOSE->{closes++;if(deferTab){tab=null;waitingTab=4;}menu=null;menuIdentity=null;context=new AutomationContext(1,true,true,Set.of());}}return PestSprayTask.Effect.SENT;}
  @Override void tick(){now+=200_000_000L;if(spray.state()==PestSprayObservation.State.NONE){if(waitingTab>0)waitingTab--;else applyTab();}if(clicks==1&&!selectedUpdate){selectedUpdate=true;selected(true,false);parent.onSystemMessage(1,failSelection?"Sprayonator! Your selected material is now Wrong Material!":"Sprayonator! Your selected material is now Test Material!",now);}parent.tick(now);}
 }
 public static void main(String[]args){
  var p=new P();check(p.parent.request(PestSprayPlanTest.policy(),p.now),"wrong-selected known tool must enter original-root selection, not silently fail or use wrong material");for(int i=0;i<40&&p.parent.active();i++)p.tick();check(p.parent.state()==PestSprayTask.State.COMPLETE&&p.opens==1&&p.clicks==1&&p.closes==1&&p.uses==1&&p.equips==1&&p.restores==1&&p.selected==0&&!p.session.active()&&p.stops==0&&p.demands==1&&p.disposals==1,"one root: settle/equip/select + appliedmetadata/GAME/ownedclose + sprayreceipt + exactrestore "+p.parent.state());
  p=new P();p.failSelection=true;check(p.parent.request(PestSprayPlanTest.policy(),p.now),"second explicit run");for(int i=0;i<40&&p.parent.active();i++)p.tick();check(!p.parent.active()&&p.uses==0&&p.closes==0&&p.restores==0&&p.stops==1&&!p.session.active(),"wrong selection acknowledgement cannot fall through to material use, close/repair or Farm restart");
  p=new P();p.deferTab=true;check(p.parent.request(PestSprayPlanTest.policy(),p.now),"deferred fresh Tab fixture");for(int i=0;i<50&&p.parent.active();i++)p.tick();check(p.parent.state()==PestSprayTask.State.COMPLETE&&p.uses==1&&p.opens==1&&p.clicks==1&&p.closes==1,"owned selection close may await a genuinely refreshed None without retrying selection/use");
  p=new P();p.tickDuringStart=true;check(p.parent.request(PestSprayPlanTest.policy(),p.now),"reentrant read fixture");for(int i=0;i<50&&p.parent.active();i++)p.tick();check(p.parent.state()==PestSprayTask.State.COMPLETE&&p.uses==1,"selection startup is not mistaken for a failed/inactive child by reentrant tick");
  p=new P();p.rearmDuringStart=true;check(p.parent.request(PestSprayPlanTest.policy(),p.now),"new root fixture");for(int i=0;i<20&&p.rearmDuringStart&&p.parent.active();i++)p.tick();check(p.parent.active()&&p.session.isCurrent(p.actualRoot)&&p.demands==2&&p.disposals==1&&p.stops==1,"old selection preflight cannot finish/cancel a newer accepted parent generation");p.parent.cancel(p.now);
  System.out.println("PestSpraySelectionIntegrationTest: PASS real parent/child/original hold/receipts, one selection then one spray and restore; controlled ports, no live claim");
 }
}
